# claude-deck watcher: tells the daemon when a pane gains/loses focus or closes,
# and keeps the tab bar's status dots and timers fresh.
# Generated by claude-deck; edits are overwritten when the deck starts.
import json
import os
import socket

_RUNTIME = os.path.join(os.environ.get('XDG_RUNTIME_DIR') or f'/tmp/claude-deck-{os.getuid()}', 'claude-deck')
_SOCK = os.path.join(_RUNTIME, 'daemon.sock')
_STATE = os.path.join(_RUNTIME, 'state.json')
_timer = {'started': False, 'mtime': 0.0, 'ticks': 0}


def _send(msg: dict) -> None:
    try:
        s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        s.settimeout(0.1)
        s.connect(_SOCK)
        s.sendall((json.dumps(msg) + '\n').encode())
        s.close()
    except OSError:
        pass


def _refresh(boss) -> None:
    for tm in boss.all_tab_managers:
        tm.mark_tab_bar_dirty()


_last_order = {'ids': None}


def _order(boss) -> list:
    """Every pane in on-screen order: tabs left to right, and inside a tab
    reading order (top to bottom, then left to right)."""
    ids = []
    for tm in boss.all_tab_managers:
        for tab in tm:
            ws = list(tab)
            ws.sort(key=lambda w: (w.geometry.top // 8, w.geometry.left))
            ids.extend(w.id for w in ws)
    return ids


def _send_order(boss) -> None:
    try:
        ids = _order(boss)
    except Exception:
        return
    if ids != _last_order['ids']:
        _last_order['ids'] = ids
        _send({'op': 'order', 'windows': ids})


def on_tab_bar_dirty(boss, window, data) -> None:
    _send_order(boss)


def _tick(timer_id) -> None:
    from kitty.boss import get_boss
    boss = get_boss()
    # Panes moving inside a tab don't touch the tab bar; check the order here too.
    _send_order(boss)
    try:
        mtime = os.stat(_STATE).st_mtime
    except OSError:
        mtime = 0.0
    _timer['ticks'] += 1
    # Redraw when the state changed, and every 15 s so "4m" timers advance.
    if mtime != _timer['mtime'] or _timer['ticks'] % 30 == 0:
        _timer['mtime'] = mtime
        _refresh(boss)


def on_load(boss, data) -> None:
    if not _timer['started']:
        from kitty.fast_data_types import add_timer
        _timer['started'] = True
        add_timer(_tick, 0.5, True)


def on_focus_change(boss, window, data) -> None:
    _send({'op': 'focus', 'kitty_window': window.id, 'focused': bool(data.get('focused'))})


def on_close(boss, window, data) -> None:
    _send({'op': 'closed', 'kitty_window': window.id})
